package hard;public class KClosestPointsToOrigin{public static int[][]kClosest(int[][]p,int k){java.util.PriorityQueue<int[]>pq=new java.util.PriorityQueue<>((a,b)->b[0]*b[0]+b[1]*b[1]-(a[0]*a[0]+a[1]*a[1]));for(int[]pt:p){pq.offer(pt);if(pq.size()>k)pq.poll();}int[][]r=new int[k][2];int i=0;while(!pq.isEmpty())r[i++]=pq.poll();return r;}public static void main(String[]args){System.out.println("K closest works\n");}}
